// Where media files live. Local disk in development (served at /media); in
// production point MEDIA_BASE_URL at a CDN in front of the same files, or
// swap in an object-storage implementation of MediaStorage.
import { mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import path from 'node:path';

export interface MediaStorage {
  put(key: string, data: Buffer, contentType: string): Promise<void>;
  get(key: string): Promise<Buffer>;
  remove(keys: string[]): Promise<void>;
  url(key: string): string;
}

/** Keys are generated by the server: "2026/10/<uuid>/<name>.<ext>" (mp4 for reels). Anything else is refused. */
const KEY = /^\d{4}\/\d{2}\/[0-9a-f-]{36}\/[a-z0-9-]+\.(webp|jpg|png|mp4)$/;

export class LocalStorage implements MediaStorage {
  constructor(
    private readonly dir: string,
    private readonly baseUrl: string,
  ) {}

  private file(key: string): string {
    if (!KEY.test(key)) throw new Error(`invalid media key: ${key}`);
    return path.join(this.dir, ...key.split('/'));
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.file(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data);
  }

  get(key: string): Promise<Buffer> {
    return readFile(this.file(key));
  }

  async remove(keys: string[]): Promise<void> {
    await Promise.all(keys.map((k) => rm(this.file(k), { force: true })));
  }

  url(key: string): string {
    return `${this.baseUrl}/${key}`;
  }
}

/** In-memory storage for tests. */
export class MemoryStorage implements MediaStorage {
  readonly files = new Map<string, Buffer>();
  constructor(private readonly baseUrl = 'http://media.test') {}
  async put(key: string, data: Buffer): Promise<void> {
    if (!KEY.test(key)) throw new Error(`invalid media key: ${key}`);
    this.files.set(key, data);
  }
  async get(key: string): Promise<Buffer> {
    const f = this.files.get(key);
    if (!f) throw new Error('not found');
    return f;
  }
  async remove(keys: string[]): Promise<void> {
    for (const k of keys) this.files.delete(k);
  }
  url(key: string): string {
    return `${this.baseUrl}/${key}`;
  }
}
